-- =====================================================================
-- 016 — Supervisores (com código) e Representantes/RCA
-- ---------------------------------------------------------------------
-- Fontes (18/08/2026): REPRESENTANTES.xlsx (258 RCAs, arquivo oficial) e
-- a lista de supervisores com código enviada em imagem pela operação.
-- ATENÇÃO: os supervisores foram transcritos de IMAGEM — os códigos devem
-- ser conferidos pela Logística; um errado se corrige cadastrando o certo
-- pela tela (o formato é livre) e avisando para remover o incorreto.
-- =====================================================================

CREATE TABLE IF NOT EXISTS dim_representantes (
    nome      TEXT PRIMARY KEY,
    criado_em TIMESTAMPTZ NOT NULL DEFAULT now()
);


